using System;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;

namespace RPCore.Tests
{
    public class InventoryArmoryTests
    {
        static ArmoryObservation Gun(int hash=1,int type=10,int ammo=40)=>new ArmoryObservation{Weapon=new CharacterWeapon{Hash=hash,AmmoType=type,Tint=2,Clip=12,Components=new List<CharacterAttachment>{new CharacterAttachment{Hash=90,Tint=-1}}},Ammo=ammo};
        static InvData Legacy()=>new InvData{Items=new Dictionary<string,int>{{"burger",2}},Containers=new Dictionary<string,Dictionary<string,int>>{{"home",new Dictionary<string,int>{{"future",7}}}},GridSlots=new List<string>{null,"burger"},Extra=new Dictionary<string,JToken>{{"Future",new JObject{{"keep",true}}}}};
        [Fact] public void ImportsEquipmentWithoutConsumingLegacyItems(){var d=Legacy();int saves=0;Assert.True(InventoryArmoryRules.Import(ref d,new[]{Gun()},n=>saves++));Assert.Equal(1,saves);Assert.Equal(1,d.Items[InventoryArmoryRules.WeaponId(1)]);Assert.Equal(40,d.Items[InventoryArmoryRules.AmmoId(10)]);Assert.Equal(2,d.Items["burger"]);Assert.Equal(7,d.Containers["home"]["future"]);Assert.True((bool)d.Extra["Future"]["keep"]);Assert.Equal("burger",d.GridSlots[1]);Assert.Equal(90,d.Armory.Weapons[InventoryArmoryRules.WeaponId(1)].Components[0].Hash);}
        [Fact] public void SharedAmmoIsNotAddedPerWeapon(){var d=Legacy();InventoryArmoryRules.Import(ref d,new[]{Gun(),Gun(2)},n=>{});Assert.Equal(40,d.Items[InventoryArmoryRules.AmmoId(10)]);Assert.Equal(2,d.Armory.Weapons.Count);}
        [Fact] public void DifferentAmmoTypesRemainSeparate(){var d=Legacy();InventoryArmoryRules.Import(ref d,new[]{Gun(),Gun(2,20,80)},n=>{});Assert.Equal(40,d.Items[InventoryArmoryRules.AmmoId(10)]);Assert.Equal(80,d.Items[InventoryArmoryRules.AmmoId(20)]);}
        [Fact] public void RescanningCannotRestoreDiscardedOrStoredGun(){var d=Legacy();InventoryArmoryRules.Import(ref d,new[]{Gun()},n=>{});d.Items.Remove(InventoryArmoryRules.WeaponId(1));d.Items[InventoryArmoryRules.AmmoId(10)]=3;int writes=0;InventoryArmoryRules.Import(ref d,new[]{Gun(ammo:250)},n=>writes++);Assert.Equal(0,writes);Assert.False(d.Items.ContainsKey(InventoryArmoryRules.WeaponId(1)));Assert.Equal(3,d.Items[InventoryArmoryRules.AmmoId(10)]);}
        [Fact] public void NewGunWithSharedPoolDoesNotDuplicateExistingReserve(){var d=Legacy();InventoryArmoryRules.Import(ref d,new[]{Gun()},n=>{});InventoryArmoryRules.Import(ref d,new[]{Gun(2,10,45)},n=>{});Assert.Equal(45,d.Items[InventoryArmoryRules.AmmoId(10)]);}
        [Fact] public void ImportFailureKeepsOriginalObjectAndAllFields(){var d=Legacy();var original=d;string before=JsonConvert.SerializeObject(d);Assert.Throws<IOException>(()=>InventoryArmoryRules.Import(ref d,new[]{Gun()},n=>throw new IOException()));Assert.Same(original,d);Assert.Equal(before,JsonConvert.SerializeObject(d));}
        [Fact] public void AmmoSaveFailureCanRetryWithoutLosingOrMintingRounds(){var d=Legacy();InventoryArmoryRules.Import(ref d,new[]{Gun()},n=>{});var original=d;Assert.Throws<IOException>(()=>InventoryArmoryRules.SetAmmo(ref d,10,37,n=>throw new IOException()));Assert.Same(original,d);Assert.Equal(40,d.Items[InventoryArmoryRules.AmmoId(10)]);Assert.True(InventoryArmoryRules.SetAmmo(ref d,10,37,n=>{}));Assert.Equal(37,d.Items[InventoryArmoryRules.AmmoId(10)]);}
        [Theory] [InlineData(40,40,39,39)] [InlineData(40,40,40,40)] [InlineData(40,40,44,44)] [InlineData(100,40,35,95)] [InlineData(1,40,30,0)] [InlineData(999999,10,20,1000000)]
        public void UsesActualNativeAmmoDeltaIncludingAutomaticFireAndPickups(int stored,int before,int after,int expected)=>Assert.Equal(expected,InventoryArmoryRules.ReconcileAmmo(stored,before,after));
        [Theory] [InlineData(-1)] [InlineData(1000001)] public void InvalidAmmoRejectedWithoutSaving(int ammo){var d=Legacy();int writes=0;Assert.False(InventoryArmoryRules.Import(ref d,new[]{Gun(ammo:ammo)},n=>writes++));Assert.Equal(0,writes);Assert.Null(d.Armory);}
        [Fact] public void CorruptArmoryIsPreserved(){var d=Legacy();d.Armory=new InventoryArmory{Weapons=null};string before=JsonConvert.SerializeObject(d);Assert.False(InventoryArmoryRules.Import(ref d,new[]{Gun()},n=>throw new Exception()));Assert.Equal(before,JsonConvert.SerializeObject(d));}
        [Fact] public void UnknownPoolCannotBeUsedToMintItems(){var d=Legacy();InventoryArmoryRules.Import(ref d,new[]{Gun()},n=>{});Assert.False(InventoryArmoryRules.SetAmmo(ref d,999,500,n=>throw new Exception()));}
        [Fact] public void SerializationRetainsAttachmentAndExtensionMetadata(){var d=Legacy();var o=Gun();o.Weapon.Extra=new Dictionary<string,JToken>{{"FutureGun","keep"}};o.Weapon.Components[0].Extra=new Dictionary<string,JToken>{{"FutureAttachment",true}};InventoryArmoryRules.Import(ref d,new[]{o},n=>{});d=JsonConvert.DeserializeObject<InvData>(JsonConvert.SerializeObject(d));Assert.True(d.Armory.Valid);InventoryArmoryRules.SetAmmo(ref d,10,0,n=>{});var w=d.Armory.Weapons[InventoryArmoryRules.WeaponId(1)];Assert.Equal("keep",(string)w.Extra["FutureGun"]);Assert.True((bool)w.Components[0].Extra["FutureAttachment"]);Assert.Equal(2,w.Tint);Assert.Equal(12,w.Clip);}
        [Fact] public void MeleeDoesNotCreateAnAmmoPool(){var d=Legacy();InventoryArmoryRules.Import(ref d,new[]{Gun(type:0,ammo:0)},n=>{});Assert.False(d.Items.ContainsKey(InventoryArmoryRules.AmmoId(0)));}
        [Fact] public void EmptyMigrationIsDurableAndIdempotent(){var d=Legacy();int writes=0;Assert.True(InventoryArmoryRules.Import(ref d,Array.Empty<ArmoryObservation>(),n=>writes++));Assert.True(InventoryArmoryRules.Import(ref d,Array.Empty<ArmoryObservation>(),n=>writes++));Assert.Equal(1,writes);Assert.True(d.Armory.Valid);}
        [Theory] [InlineData(-1)] [InlineData(int.MinValue)] [InlineData(int.MaxValue)] public void UnsignedNativeHashesHaveStableIds(int hash){string id=InventoryArmoryRules.WeaponId(hash);Assert.Equal(15,id.Length);Assert.Equal("weapon_"+unchecked((uint)hash).ToString("x8"),id);}
        [Fact] public void ImportedMetadataHasNoMutableAliasToObservation(){var d=Legacy();var o=Gun();InventoryArmoryRules.Import(ref d,new[]{o},n=>{});o.Weapon.Components.Clear();Assert.Single(d.Armory.Weapons[InventoryArmoryRules.WeaponId(1)].Components);}
        [Fact] public void StorageMovesPreserveWeaponAccessoriesAndSharedAmmo(){var d=Legacy();InventoryArmoryRules.Import(ref d,new[]{Gun()},n=>{});string id=InventoryArmoryRules.WeaponId(1);Assert.True(InventoryTransfers.Move(d,"home:eclipse",id,1,true,200,200,_=>0,n=>{},out d));Assert.False(d.Items.ContainsKey(id));Assert.Equal(1,d.Containers["home:eclipse"][id]);Assert.Equal(40,d.Items[InventoryArmoryRules.AmmoId(10)]);Assert.Equal(90,d.Armory.Weapons[id].Components[0].Hash);Assert.True(InventoryTransfers.Move(d,"home:eclipse",id,1,false,200,200,_=>0,n=>{},out d));Assert.Equal(1,d.Items[id]);Assert.Equal(2,d.Armory.Weapons[id].Tint);}
        [Theory] [InlineData(null,true)] [InlineData("homestorage",true)] [InlineData("hunting",false)] [InlineData("characters",false)] [InlineData("needs_sleep",false)]
        public void StoragePermittedButActivitiesExcluded(string owner,bool allowed)=>Assert.Equal(allowed,InventoryArmoryRules.ActivityAllows(owner));
        [Fact] public void ThrowableStackCountsProjectilesWithoutCreatingExtraBulletItem(){var d=Legacy();var o=Gun(ammo:5);o.Stacked=true;InventoryArmoryRules.Import(ref d,new[]{o},n=>{});string id=InventoryArmoryRules.WeaponId(1);Assert.Equal(5,d.Items[id]);Assert.False(d.Items.ContainsKey(InventoryArmoryRules.AmmoId(10)));Assert.Equal(id,InventoryArmoryRules.PoolItem(d.Armory,10));InventoryArmoryRules.SetAmmo(ref d,10,4,n=>{});Assert.Equal(4,d.Items[id]);InventoryArmoryRules.SetAmmo(ref d,10,0,n=>{});Assert.Equal(0,d.Items[id]);}
        [Fact] public void PartialThrowableStorageCannotRestoreOldStackOnRescan(){var d=Legacy();var o=Gun(ammo:5);o.Stacked=true;InventoryArmoryRules.Import(ref d,new[]{o},n=>{});string id=InventoryArmoryRules.WeaponId(1);Assert.True(InventoryTransfers.Move(d,"trunk:test",id,3,true,200,200,_=>0,n=>{},out d));InventoryArmoryRules.Import(ref d,new[]{o},n=>throw new Exception());Assert.Equal(2,d.Items[id]);Assert.Equal(3,d.Containers["trunk:test"][id]);Assert.Contains(id,d.Armory.Stacked);}
        [Fact] public void InvalidMixedThrowableAmmoPoolIsRefusedBeforeSaving(){var d=Legacy();var o=Gun(ammo:5);o.Stacked=true;Assert.False(InventoryArmoryRules.Import(ref d,new[]{o,Gun(2)},n=>throw new Exception()));Assert.Null(d.Armory);}
    }
}
